import { createAction, createSlice, PayloadAction } from '@reduxjs/toolkit';
import { IProfile, IProfileDrawerInitiator, IProfileSigninType } from './profile.models';

export const initialState: IProfile = {
  drawerOpen: false,
  drawerOpenInitiator: undefined,
  signinDialogOpen: undefined,
};

const getProfile = createAction<{
  drawerOpen: boolean;
}>('key');

const profileSlice = createSlice({
  name: 'profile',
  initialState,
  reducers: {
    setLoginDialogOpen(state, action: PayloadAction<IProfileSigninType>) {
      return {
        ...state,
        signinDialogOpen: action.payload,
      };
    },
    toggleProfileDrawer(state, action: PayloadAction<{ open: boolean; initiator?: IProfileDrawerInitiator }>) {
      return {
        ...state,
        drawerOpen: action.payload.open,
        drawerOpenInitiator: action.payload.open === false ? action.payload.initiator : undefined,
      };
    },
    reset() {
      return {
        ...initialState,
      };
    },
  },
});

const { actions } = profileSlice;
export const { reducer: profileReducer, name: profileSliceKey } = profileSlice;
export const profileActions = {
  ...actions,
  getProfile,
};
