import { Grid, Typography, Divider, Collapse, useTheme } from '@mui/material';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { makeDocHash } from 'database/firebase/firebase-helper';
import { setDoc, doc } from 'firebase/firestore';
import moment from 'moment';
import React from 'react';
import { IComment } from 'stores/blog/models';
import { CommentForm } from './comment-form';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import ReplyIcon from '@mui/icons-material/Reply';
// import ShareIcon from '@mui/icons-material/Share';
// import FlagIcon from '@mui/icons-material/Flag';
import { Action } from './comment-actions';
import { calculateTimeSince } from 'app/utils/helpers/date-helper';
import { GenericTooltip } from 'app/components/tooltip/generic-tooltip';

export const Reply = ({
  blogId,
  comment,
  lastComment = false,
  level = 0,
  commentParentsRemaining = false,
  ...rest
}: {
  [x: string]: any;
  blogId: string;
  comment: IComment;
  lastComment: boolean;
  level: number;
  commentParentsRemaining: boolean;
}) => {
  const theme = useTheme();
  const [replyOpen, setReplyOpen] = React.useState<boolean>(false);
  const { firestore } = React.useContext(FirebaseContext);

  const onPost = ({ comment: _comment }) => {
    return setDoc(doc(firestore, `blogs/${blogId}/comments`, makeDocHash(20)), _comment)
      .then(() => {
        setReplyOpen(false);
        return Promise.resolve();
      })
      .catch(() => {
        return Promise.reject();
      });
  };

  const [openComments, setOpenComments] = React.useState<boolean>(true);

  const numReplies = React.useMemo(() => {
    // const totalCount = 0;
    const replyCount = comm => {
      if (!comm.replies || comm.replies.length === 0) return 0;
      let total = comm.replies.length;
      for (const reply of comm.replies) {
        total += replyCount(reply);
      }
      return total;
    };
    let total = replyCount(comment);
    return total;
  }, [comment]);

  return (
    <Grid
      key={rest.key}
      container
      sx={
        {
          /* paddingLeft: `${level * 24}px` */
        }
      }
    >
      {/* Change this to have a left border */}
      <Grid item xs={12}>
        <Grid
          item
          container
          xs={12}
          sx={{
            borderLeft: level > 0 ? `0px solid ${theme.palette.divider}` : `0px solid white`,
            paddingLeft: `${level * 24}px`,
            // paddingLeft: level > 0 ? '12px' : '0px',
          }}
        >
          <Grid item container xs={12} sx={{ paddingLeft: comment.replies.length === 0 && level > 0 ? '24px' : '0px' }}>
            <Grid item xs={12}>
              <Grid container item xs={12} sx={{ height: '24px' }}>
                <Grid item onClick={() => setOpenComments(prev => !prev)} sx={{ cursor: 'pointer' }}>
                  {comment.replies?.length > 0 ? (
                    <>{openComments ? <ExpandMoreIcon color="secondary" /> : <ExpandLessIcon color="secondary" />}</>
                  ) : level === 0 ? (
                    <div style={{ width: '24px', height: '20px' }} />
                  ) : null}
                </Grid>

                <Grid item>
                  <Typography
                    variant="subtitle1"
                    color="text.secondary"
                  >{`${comment.firstName} ${comment.lastName}`}</Typography>
                </Grid>
                {/* <Grid item sx={{ padding: '0px 12px' }}>
                  <Typography variant="subtitle2" color="text.secondary" sx={{ marginTop: '3px' }}>
                    {'•'}
                  </Typography>
                </Grid>
                <Grid item>
                  <Typography variant="subtitle2" color="text.secondary" sx={{ marginTop: '3px' }}>
                    {calculateTimeSince(moment(comment.date))}
                  </Typography>
                </Grid> */}
              </Grid>
            </Grid>
            <Grid
              item
              container
              xs={12}
              sx={{ paddingLeft: comment.replies?.length > 0 || level === 0 ? '24px' : '0px' }}
            >
              <Grid item xs={12} container>
                <Grid item>
                  <GenericTooltip
                    title={
                      <Typography variant="body2" color="text.primary">
                        {moment(comment.date).format('MMM DD, YYYY hh:MM A')}
                      </Typography>
                    }
                  >
                    <Typography variant="subtitle2" color="text.secondary">
                      {calculateTimeSince(moment(comment.date))}
                    </Typography>
                  </GenericTooltip>
                </Grid>
              </Grid>
              <Grid item xs={12} sx={{ marginTop: '6px' }}>
                <Typography variant="body1" color="text.primary" sx={{ whiteSpace: 'pre-line' }}>
                  {comment.comment}
                </Typography>
              </Grid>
              <Grid item xs={12} sx={{ marginTop: '12px' }}>
                <Grid container spacing={3} wrap="nowrap">
                  <Grid item>
                    <Action Icon={ReplyIcon} text="Reply" onClick={() => setReplyOpen(true)} />
                  </Grid>
                  {/* <Grid item>
                    <Action Icon={ShareIcon} text="Share" disabled />
                  </Grid> */}
                  {/* <Grid item>
                    <Action Icon={FlagIcon} text="Report" disabled />
                  </Grid> */}
                </Grid>
              </Grid>
              {!openComments && comment.replies.length !== 0 && (
                <Grid
                  item
                  sx={{ cursor: 'pointer', '&:hover': { textDecoration: 'underline' } }}
                  onClick={() => setOpenComments(true)}
                >
                  <Typography variant="body1">{`${numReplies} ${numReplies > 1 ? 'replies' : 'reply'}...`}</Typography>
                </Grid>
              )}
            </Grid>
          </Grid>
        </Grid>
        {/* Add new comment textfields here */}
        {replyOpen && (
          <Grid item sx={{ paddingTop: '12px' }}>
            <CommentForm
              blogId={blogId}
              commentId={comment.id}
              onPost={onPost}
              onCancel={() => setReplyOpen(false)}
              reply
            />
          </Grid>
        )}
        {(!lastComment || commentParentsRemaining) && (
          <Grid item xs={12}>
            <Divider sx={{ margin: '6px 0px' }} />
          </Grid>
        )}
        <Collapse in={openComments}>
          {comment.replies?.length > 0 && (
            <Grid item xs={12}>
              {comment.replies.map((reply, index) => (
                <Reply
                  key={index}
                  blogId={blogId}
                  comment={reply}
                  level={level + 1}
                  lastComment={index === comment.replies.length - 1 && reply.replies.length === 0}
                  commentParentsRemaining={commentParentsRemaining || index !== comment.replies?.length - 1}
                />
              ))}
            </Grid>
          )}
        </Collapse>
      </Grid>
    </Grid>
  );
};
