import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { getBlogs } from './blog.actions';
import { IBlogs, IBlog, IComment } from './models';

export const initialState: IBlogs = {
  blogs: [],
  comments: [],
};

const blogSlice = createSlice({
  name: 'blogs',
  initialState,
  reducers: {
    setBlogs(state, action: PayloadAction<IBlog[]>) {
      return {
        ...state,
        blogs: action.payload,
      };
    },
    setComments(state, action: PayloadAction<IComment[]>) {
      return {
        ...state,
        comments: action.payload,
      };
    },
    resetComments(state) {
      return {
        ...state,
        comments: undefined,
      };
    },
    reset() {
      return {
        ...initialState,
      };
    },
  },
});

const { actions } = blogSlice;
export const { reducer: blogReducer, name: blogSliceKey } = blogSlice;
export const blogActions = {
  ...actions,
  getBlogs,
};
