import { useNavigation } from "app/utils/hooks/use-navigation";

export const useMenu = () => {
  const {  cv, penn, blogs } = useNavigation();
  const menuItems = [
    {
      title: 'CV',
      onClick: () => cv(),
    },
    {
      title: 'penn',
      onClick: () => penn(),
    },
    {
      title: 'blog',
      onClick: () => blogs(),
    },
  ];

  return { menuItems }
}