import { Button, useTheme } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';
import { IProfileSigninType } from 'stores/profile/profile.models';
import { profileActions } from 'stores/profile/profile.redux';

interface SignUpActionsProps {
  onSignInClick?: () => void;
  onSignUpClick?: () => void;
}

export const SignUpActions = ({ onSignInClick, onSignUpClick, ...props }: SignUpActionsProps) => {
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const theme = useTheme();

  return (
    <>
      <Button
        disableElevation
        variant="contained"
        size="small"
        color="secondary"
        sx={{
          borderRadius: '28px',
          height: '28px',
          marginRight: '-22px',
          zIndex: 500,
          border:
            theme.palette.mode === 'light'
              ? `1px solid ${theme.palette.custom.secondaryButtonBorder}`
              : `1px solid ${theme.palette.custom.secondaryButtonBorder}`,
          //border: theme.palette.mode === 'light' ? '1px solid white' : '1px solid #d9d9d9',
        }}
        onClick={() => {
          onSignUpClick?.();
          dispatch(profileActions.setLoginDialogOpen(IProfileSigninType.signUp));
        }}
      >
        {t('profile.account-form.signup.submit')}
      </Button>
      <Button
        disableElevation
        variant="contained"
        size="small"
        color="primary"
        sx={{
          borderRadius: '28px',
          height: '28px',
          paddingLeft: '28px',
          border:
            theme.palette.mode === 'light'
              ? `1px solid ${theme.palette.custom.secondaryButtonBorder}`
              : `1px solid ${theme.palette.custom.secondaryButtonBorder}`,
        }}
        onClick={() => {
          onSignInClick?.();
          dispatch(profileActions.setLoginDialogOpen(IProfileSigninType.signIn));
        }}
      >
        {t('profile.account-form.signin.submit')}
      </Button>
    </>
  );
};
