import { createSelector } from '@reduxjs/toolkit';
import { RootState } from 'types';
import { initialState } from './profile.redux';

const selectDomain = (state: RootState) => state?.profile || initialState;

export const selectProfile = createSelector([selectDomain], state => state);

export const selectSigninDialogOpen = createSelector([selectDomain], state => state.signinDialogOpen);