import { makeStyles } from 'tss-react/mui';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import WarningIcon from '@mui/icons-material/Warning';
import { isNullOrUndefined } from 'app/utils/helper';
import { Grid, Typography } from '@mui/material';
import { BannerActions } from './banner-actions';
import { IBannerAction } from './models';
import { useTranslation } from 'react-i18next';

const useStyles = makeStyles()(theme => ({
  root: {
    width: '100%',
    padding: '12px 6px',
    display: 'flex',
    alignItems: 'center',
    borderRadius: '28px',
  },
  subRoot: {
    width: '100%',
  },
  rootWarning: {
    backgroundColor: theme.palette.warning.main,
    border: '1px solid #FFA22E',
    justifyContent: 'left',
    '& #custom-banner-text': {
      color: '#fff',
    },
  },
  rootError: {
    backgroundColor: theme.palette.error.main,
    '& #custom-banner-text': {
      color: '#fff',
    },
  },
  icon: {
    marginLeft: '6px',
    marginRight: '12px',
    color: theme.palette.common.white,
  },
  action: {
    marginLeft: '12px',
  },
}));

export const Banner = ({
  message,
  severity = 'warning',
  justify = 'flex-start',
  action,
}: {
  message: string;
  severity?: 'warning' | 'error';
  justify?: 'flex-start' | 'center' | 'flex-end';
  action?: IBannerAction;
}) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();

  return (
    <Grid
      container
      justifyContent={justify}
      direction={'row'}
      alignContent="center"
      className={cx(classes.root, {
        [classes.rootWarning]: severity === 'warning',
        [classes.rootError]: severity === 'error',
      })}
      wrap="nowrap"
    >
      <Grid item>
        <Grid container className={classes.subRoot} wrap="nowrap" alignContent="center" alignItems="center" style={{ display: 'flex' }}>
          <Grid item sx={{ display: 'flex' }}>
            {severity === 'warning' && <WarningIcon className={classes.icon} />}
            {severity === 'error' && <ErrorOutlineIcon className={classes.icon} />}
          </Grid>
          <Grid id="custom-banner-text" item>
            <Typography variant="body1">{t(message)}</Typography>
          </Grid>
        </Grid>
      </Grid>
      {!isNullOrUndefined(action) && (
        <Grid item className={classes.action}>
          <BannerActions action={action!} />
        </Grid>
      )}
    </Grid>
  );
};
