interface SigninDialogProps {
  open: boolean;
  onClose: () => void;
}

const actionWidth = '275px';
const defaultValues = {
  username: '',
  email: '',
  password: '',
};

const GoogleButton = ({ onError }: { onError: (error: FirebaseError) => void }) => {
  const { t } = useTranslation();
  const { signInUser } = useAuth();
  const dispatch = useDispatch();
  const { reset } = useFormContext();
  return (
    <DialogButton
      onClick={() => {
        signInUser({ authType: EAuthType.google })
          .then(() => {
            dispatch(profileActions.setLoginDialogOpen(undefined));
            reset(defaultValues);
          })
          .catch(error => {
            if (error instanceof FirebaseError) {
              onError(error);
              console.info('@JAKE - Google Login Error');
            }
          });
      }}
      text={t('profile.account-form.google-button')}
      icon={<img src={Google} style={{ height: '20px', width: '20px' }} alt="Google" />}
    />
  );
};

