const DialogButton = ({
  onClick,
  text,
  icon,
  disabled,
}: {
  onClick: () => void;
  text: string;
  icon: React.ReactNode;
  disabled?: boolean;
}) => {
  return (
    <Button
      sx={{ justifyContent: 'space-between' }}
      startIcon={icon}
      variant="contained"
      fullWidth
      onClick={onClick}
      disableElevation
      disabled={disabled}
    >
      {text}
      <div style={{ width: '20px', height: '20px' }} />
    </Button>
  );
};

const PasswordTextField = ({ ...props }: TextFieldProps) => {
  const { t } = useTranslation();
  const { control } = useFormContext();
  const signinDialogOpenType = useSelector(selectSigninDialogOpen);
  const [showPassword, setShowPassword] = React.useState<'text' | 'password'>('password');

  return (
    <Controller
      control={control}
      name="password"
      render={({ field, formState }) => (
        <TextField
          key={signinDialogOpenType}
          {...field}
          size="small"
          label={t('profile.account-form.password')}
          type={showPassword}
          variant="outlined"
          fullWidth
          {...props}
          error={!!formState.errors.password}
          helperText={formState.errors.password?.message.toString()}
          autoComplete={signinDialogOpenType === IProfileSigninType.signUp ? 'new-password' : 'current-password'}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end" sx={{ cursor: 'pointer' }}>
                {showPassword === 'password' ? (
                  <VisibilityIcon color="primary" onClick={() => setShowPassword('text')} />
                ) : (
                  <VisibilityOffIcon color="primary" onClick={() => setShowPassword('password')} />
                )}
              </InputAdornment>
            ),
          }}
        />
      )}
    />
  );
};

export const SigninDialog = ({ open, onClose, ...props }: SigninDialogProps) => {
  const { createUser, signInUser } = useAuth();
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const signinDialogOpenType = useSelector(selectSigninDialogOpen);
  const [loginError, setLoginError] = React.useState<string | undefined>();
  const theme = useTheme();
  const desktop = useMediaQuery(theme.breakpoints.down('sm'));

  const { handleSubmit, reset, formState, control, setError, ...restFormMethods } = useForm({
    defaultValues: {
      username: null,
      email: null,
      password: null,
    },
    resolver: yupResolver(
      yup.object({
        username:
          signinDialogOpenType === IProfileSigninType.signUp ? yup.string().required() : yup.string().nullable(),
        email: yup.string().email().required(),
        password: yup.string().required(),
      }),
    ),
  });

  React.useEffect(() => {
    if (isNullOrUndefined(signinDialogOpenType)) {
      setLoginError(undefined);
      reset(defaultValues);
    }
    return () => {
      setLoginError(undefined);
      reset(defaultValues);
    };
  }, [reset, signinDialogOpenType]);

  const onError = React.useCallback(
    (error: FirebaseError) => {
      switch (error.code) {
        case 'auth/weak-password':
          if (signinDialogOpenType === IProfileSigninType.signUp) {
            setLoginError('Password must be at least 6 characters');
            setError('password', { message: '', type: 'validate' });
          }
          break;
        case 'auth/email-already-in-use':
          // Email is already used
          if (signinDialogOpenType === IProfileSigninType.signUp) {
            setError('email', { message: '', type: 'validate' });
          }
          setLoginError('Email is already in use');
          break;
        case 'auth/account-exists-with-different-credential':
          setLoginError('Email used with different provider');
          // Email is already used by a different provider
          break;
        case 'auth/wrong-password':
          // custom account, invalid password
          setLoginError('Invalid credentials');
          setError('email', { message: '', type: 'validate' });
          setError('password', { message: '', type: 'validate' });
          break;
        case 'auth/user-not-found':
          // user doesn't exist
          setLoginError('User not found');
          setError('email', { message: '', type: 'validate' });
          setError('password', { message: '', type: 'validate' });
          break;
        default:
          setLoginError('Unknown error');
          break;
      }
    },
    [setError, signinDialogOpenType],
  );

  const submitForm = React.useCallback(
    (updates, e) => {
      switch (signinDialogOpenType) {
        case IProfileSigninType.signIn:
          signInUser({
            authType: EAuthType.email,
            emailPassword: { email: updates.email, password: updates.password },
          })
            .then(() => {
              dispatch(profileActions.setLoginDialogOpen(undefined));
              reset(defaultValues);
            })
            .catch(error => {
              onError(error);
              console.info('@JAKE - ERROR CREATING USER FROM DIALOG', error);
            });
          break;
        case IProfileSigninType.signUp:
          createUser({
            authType: EAuthType.email,
            username: updates.username,
            email: updates.email,
            password: updates.password,
          })
            .then(() => {
              dispatch(profileActions.setLoginDialogOpen(undefined));
              reset(defaultValues);
            })
            .catch(error => {
              onError(error);
              console.info('@JAKE - ERROR CREATING USER FROM DIALOG', error);
            });
          break;
        default:
          break;
      }
    },
    [signinDialogOpenType, signInUser, createUser, dispatch, reset, onError],
  );

  const SignInDialogContent = React.useMemo(() => {
    switch (signinDialogOpenType) {
      case IProfileSigninType.signUp:
      case IProfileSigninType.signIn:
        return (
          <div
            style={{
              display: 'flex',
              width: actionWidth,
            }}
          >
            <FormProvider {...{ handleSubmit, reset, formState, control, setError, ...restFormMethods }}>
              <form onSubmit={handleSubmit(submitForm)}>
                <Grid container spacing={3}>
                  <Grid item xs={12}>
                    <Typography variant="h5" sx={{ textAlign: 'center' }}>
                      {signinDialogOpenType === IProfileSigninType.signIn
                        ? t('profile.account-form.signin.title')
                        : t('profile.account-form.signup.title')}
                    </Typography>
                  </Grid>
                  <Grid item container spacing={3} xs={12}>
                    {signinDialogOpenType === IProfileSigninType.signUp && (
                      <Grid item xs={12} sx={{ display: 'flex' }} justifyContent="center">
                        <Controller
                          control={control}
                          name="username"
                          rules={{
                            required: signinDialogOpenType === IProfileSigninType.signUp,
                            validate: (value, formValues) => {
                              if (value === 'jake') {
                                return 'jake is already taken';
                              }
                              return true;
                            },
                          }}
                          render={({ field, formState }) => (
                            <TextField
                              {...field}
                              size="small"
                              label={t('profile.account-form.username')}
                              variant="outlined"
                              fullWidth
                              error={!!formState.errors.username}
                              helperText={formState.errors.username?.message.toString()}
                            />
                          )}
                        />
                      </Grid>
                    )}
                    <Grid item xs={12} sx={{ display: 'flex' }} justifyContent="center">
                      <Controller
                        control={control}
                        name="email"
                        render={({ field, formState }) => (
                          <TextField
                            {...field}
                            size="small"
                            type="email"
                            label={t('profile.account-form.email')}
                            variant="outlined"
                            fullWidth
                            error={!!formState.errors.email}
                            helperText={formState.errors.email?.message.toString()}
                          />
                        )}
                      />
                    </Grid>
                    <Grid item xs={12} sx={{ display: 'flex' }} justifyContent="center">
                      <PasswordTextField />
                    </Grid>
                    <Grid item container xs={12} justifyContent="flex-end">
                      <Grid item justifyContent="flex-end">
                        <Button size="small" variant="contained" type="submit" disableElevation>
                          {signinDialogOpenType === IProfileSigninType.signIn
                            ? t('profile.account-form.signin.submit')
                            : t('profile.account-form.signup.create-account-submit')}
                        </Button>
                      </Grid>
                    </Grid>
                    <Grid item xs={12} justifyContent="center" sx={{ display: 'flex' }}>
                      <Grid container alignContent="center" alignItems="center">
                        <Grid item xs={5}>
                          <Divider />
                        </Grid>
                        <Grid item xs={2} justifyContent="center" justifyItems="center" textAlign="center">
                          {t('profile.account-form.or')}
                        </Grid>
                        <Grid item xs={5}>
                          <Divider />
                        </Grid>
                      </Grid>
                    </Grid>
                    <Grid item xs={12} sx={{ display: 'flex' }} justifyContent="center">
                      <GoogleButton onError={onError} />
                    </Grid>
                    <Grid item xs={12} sx={{ display: 'flex' }} justifyContent="center">
                      <GitHubButton onError={onError} />
                    </Grid>
                  </Grid>

                  <Grid item xs={12} sx={{ textAlign: 'center', marginBottom: '24px' }}>
                    <Typography>
                      {signinDialogOpenType === IProfileSigninType.signIn
                        ? t('profile.account-form.signin.no-account')
                        : t('profile.account-form.signup.existing-account-label')}
                      <Link
                        onClick={() => {
                          reset(defaultValues);
                          setLoginError(undefined);
                          dispatch(
                            profileActions.setLoginDialogOpen(
                              signinDialogOpenType === IProfileSigninType.signIn
                                ? IProfileSigninType.signUp
                                : IProfileSigninType.signIn,
                            ),
                          );
                        }}
                        color="text.primary"
                      >
                        {signinDialogOpenType === IProfileSigninType.signIn
                          ? t('profile.account-form.signin.create-account')
                          : t('profile.account-form.signup.existing-account-link')}
                      </Link>
                    </Typography>
                  </Grid>
                </Grid>
              </form>
            </FormProvider>
          </div>
        );
      default:
        return <div>{'Error'}</div>;
    }
  }, [
    control,
    dispatch,
    formState,
    handleSubmit,
    onError,
    reset,
    restFormMethods,
    setError,
    signinDialogOpenType,
    submitForm,
    t,
  ]);

  return (
    <GenericDialog
      fullWidth
      fullScreen={desktop}
      maxWidth="xs"
      variant="white"
      open={open}
      onClose={() => {
        reset(defaultValues);
        setLoginError(undefined);
        onClose();
      }}
      dialogTitleProps={{ text: t(''), closeButton: true }}
      color="primary"
      dialogContentProps={{
        sx: { display: 'flex', justifyContent: 'center', placeItems: 'unset !important' },
        error: !!loginError,
        errorMessage: loginError,
      }}
    >
      {SignInDialogContent}
    </GenericDialog>
  );
};
