import React from 'react';
import { onSnapshot, collection, DocumentData, QuerySnapshot } from 'firebase/firestore';
import { useInjectReducer } from 'utils/redux-injectors';
import { useDispatch } from 'react-redux';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { blogActions, blogReducer, blogSliceKey, initialState } from 'stores/blog/blog.redux';
import { IBlog } from 'stores/blog/models';
import moment from 'moment';

export const useBlogFirestore = () => {
  useInjectReducer({ key: blogSliceKey, reducer: blogReducer });
  const dispatch = useDispatch();
  const { firestore } = React.useContext(FirebaseContext);

  React.useEffect(() => {
    const blogsRef = collection(firestore, 'blogs');
    const unsubscribe = onSnapshot(blogsRef, (querySnapshot: QuerySnapshot<DocumentData, DocumentData>) => {
      const blogs: IBlog[] = querySnapshot.empty ? initialState.blogs : [];
      querySnapshot.forEach(document => {
        const data = document.data();
        blogs.push({
          id: document.id,
          date: data.date,
          title: data.title,
          header: data.header,
          content: data.content,
        });
      });
      dispatch(blogActions.setBlogs(blogs.sort((a, b) => (moment(a.date) < moment(b.date) ? -1 : 1))));
    });

    return () => {
      unsubscribe();
    };
  }, [dispatch, firestore]);
};
