import { Avatar } from '@mui/material';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { getUserInitials } from 'app/utils/user-helper';
import React from 'react';
import { useDispatch } from 'react-redux';
import { IProfileDrawerInitiator } from 'stores/profile/profile.models';
import { profileActions } from 'stores/profile/profile.redux';

interface IProfileAvatarProps {
  mobile: boolean;
  size?: string;
}

export const ProfileAvatar = ({ mobile, size }: IProfileAvatarProps) => {
  const dispatch = useDispatch();
  const { user } = React.useContext(FirebaseContext);
  const avatarSize = '30px';

  return (
    <Avatar
      variant="circular"
      sizes="small"
      sx={{
        lineHeight: 'initial',
        height: size ?? avatarSize,
        width: size ?? avatarSize,
        marginleft: '24px',
        cursor: 'pointer',
      }}
      onClick={
        !mobile
          ? e => {
              dispatch(profileActions.toggleProfileDrawer({ open: true, initiator: IProfileDrawerInitiator.appBar }));
            }
          : undefined
      }
    >
      {user.photoURL ? (
        <img src={user.photoURL} alt="profile" style={{ height: size ?? avatarSize, width: size ?? avatarSize }} />
      ) : (
        getUserInitials(user.displayName)
      )}
    </Avatar>
  );
};
