import React from 'react';
import { onSnapshot, collection, DocumentData, QuerySnapshot, query, orderBy } from 'firebase/firestore';
import { useInjectReducer } from 'utils/redux-injectors';
import { useDispatch } from 'react-redux';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { blogActions, blogReducer, blogSliceKey } from 'stores/blog/blog.redux';
import { IComment } from 'stores/blog/models';
import moment from 'moment';

export const useCommentsFirestore = (blogId: string) => {
  const [loading, setLoading] = React.useState<boolean>(false);
  useInjectReducer({ key: blogSliceKey, reducer: blogReducer });
  const dispatch = useDispatch();
  const { firestore } = React.useContext(FirebaseContext);

  React.useEffect(() => {
    const blogsRef = query(collection(firestore, `blogs/${blogId}/comments`), orderBy('date', 'asc'));
    setLoading(true);
    const unsubscribe = onSnapshot(blogsRef, (querySnapshot: QuerySnapshot<DocumentData, DocumentData>) => {
      const comments: IComment[] = [];
      querySnapshot.forEach(document => {
        const docData = document.data();
        const data: IComment = {
          id: document.id,
          blogId: blogId,
          userId: docData.userId,
          comment: docData.comment,
          parentId: docData.parentId,
          date: docData.date,
          firstName: docData.firstName,
          lastName: docData.lastName,
          replies: [],
        };

        if (data.parentId && data.parentId !== '') {
          const findParent = (commentArray): IComment | null | undefined => {
            for (let i = 0; i < commentArray.length; i++) {
              if (commentArray[i].id === data.parentId) {
                return commentArray[i];
              } else if (commentArray[i].replies?.length > 0) {
                const found = findParent(commentArray[i].replies);
                if (found) {
                  return found;
                }
              }
            }
          };
          const parentComment = findParent(comments);
          if (parentComment) {
            parentComment.replies.push?.(data);
          }
        } else if (!data.parentId) {
          data.replies = [];
          comments?.push?.(data);
        }
      });
      dispatch(blogActions.setComments(comments.sort((a, b) => (moment(a.date) < moment(b.date) ? -1 : 1))));
      setLoading(false);
    });

    return () => {
      unsubscribe();
    };
  }, [blogId, dispatch, firestore]);

  return { loading }
};
