import { Button, CircularProgress, Grid, TextField } from '@mui/material';
import React from 'react';
import { manuallyDecrementPromiseCounter, usePromiseTracker } from 'react-promise-tracker';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ErrorIcon from '@mui/icons-material/Error';
import { ICommentForm } from 'stores/blog/models';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { getUserFirstName, getUserLastName } from 'app/utils/user-helper';
import { useDispatch, useSelector } from 'react-redux';
import { profileActions } from 'stores/profile/profile.redux';
import { IProfileSigninType } from 'stores/profile/profile.models';
import { selectSigninDialogOpen } from 'stores/profile/profile.selectors';
import { isNullOrUndefined } from 'app/utils/helper';

interface CommentFormProps {
  blogId: string;
  commentId?: string;
  reply?: boolean;
  onCancel?: () => void;
  onPost: ({ comment }: { comment: ICommentForm }) => Promise<void>;
  disabled?: boolean;
}

export const CommentForm = ({ blogId, commentId, reply, onCancel, onPost, disabled }: CommentFormProps) => {
  const dispatch = useDispatch();
  const { user } = React.useContext(FirebaseContext);
  const loginPageOpen = useSelector(selectSigninDialogOpen);
  const [firstName, setFirstName] = React.useState<string>('');
  // const [firstNameError, setFirstNameError] = React.useState<boolean>(false);
  const [lastName, setLastName] = React.useState<string>('');
  const [comment, setComment] = React.useState<string>('');
  const [commentError, setCommentError] = React.useState<boolean>(false);
  const [postError, setPostError] = React.useState<boolean>(false);
  const [postCompleted, setPostCompleted] = React.useState<boolean>(false);
  const promiseTrackerArea = `post-new-comment-${blogId}-${commentId ?? 'new'}`;
  const { promiseInProgress: postInProgress } = usePromiseTracker({
    area: promiseTrackerArea,
    delay: 0,
  });

  const _onPost = () => {
    if (!user || !comment) {
      if (!user) {
        //login user
        dispatch(profileActions.setLoginDialogOpen(IProfileSigninType.signUp));
        // setFirstNameError(true);
        return;
      } else if (!comment) {
        setCommentError(true);
        return;
      }
      return;
    } else {
      setCommentError(false);
      // setFirstNameError(false);
    }

    const _comment: ICommentForm = {
      comment,
      firstName: user ? getUserFirstName(user.displayName) : firstName,
      lastName: user ? getUserLastName(user.displayName) : lastName,
      parentId: commentId ?? '',
      date: new Date().toISOString(),
      userId: user?.uid ?? ''
    };

    onPost({ comment: _comment })
      .then(success => {
        setFirstName('');
        setLastName('');
        setComment('');
        manuallyDecrementPromiseCounter(promiseTrackerArea);
        setPostCompleted(true);
        setTimeout(() => {
          setPostCompleted(false);
        }, 3000);
      })
      .catch(() => {
        manuallyDecrementPromiseCounter(promiseTrackerArea);
        setPostError(true);
        setTimeout(() => {
          setPostError(false);
        }, 3000);
      });
  };

  const commentRef = React.useRef(null);
  const onFocus = React.useCallback(
    e => {
      if (!user && isNullOrUndefined(loginPageOpen)) {
        commentRef.current?.blur();
        e.preventDefault();
        e.stopPropagation();
        dispatch(profileActions.setLoginDialogOpen(IProfileSigninType.signUp));
      }
    },
    [dispatch, loginPageOpen, user],
  );

  return (
    <Grid item container xs={12} spacing={3}>
      {!disabled && (
        <>
          <Grid item xs={12}>
            <TextField
              ref={commentRef}
              required
              size="small"
              multiline
              fullWidth
              value={comment}
              label="Share your thoughts"
              minRows={2}
              maxRows={5}
              onChange={e => {
                setCommentError(false);
                setComment(e.target.value);
              }}
              error={commentError}
              helperText={commentError ? 'Comment is required' : ''}
              InputProps={{
                onFocus: onFocus,
              }}
              disabled={!isNullOrUndefined(loginPageOpen)}
            />
          </Grid>
          {/* {!user && (
            <>
              <Grid item xs={6}>
                <TextField
                  required
                  size="small"
                  variant="outlined"
                  fullWidth
                  value={firstName}
                  label="First Name"
                  onChange={e => {
                    setFirstNameError(false);
                    setFirstName(e.target.value);
                  }}
                  error={firstNameError}
                  helperText={firstNameError ? 'First name is required' : ''}
                  autoComplete="one-time-code"
                  InputProps={{
                    autoComplete: 'one-time-code',
                  }}
                />
              </Grid>
              <Grid item xs={6}>
                <TextField
                  size="small"
                  fullWidth
                  value={lastName}
                  label="Last Name"
                  onChange={e => setLastName(e.target.value)}
                  autoComplete="one-time-code"
                  InputProps={{
                    autoComplete: 'one-time-code',
                  }}
                />
              </Grid>
            </>
          )} */}
        </>
      )}
      <Grid item container xs={12} spacing={3} justifyContent="flex-end">
        {reply && (
          <Grid item>
            <Button onClick={onCancel} color="secondary">
              {'Cancel'}
            </Button>
          </Grid>
        )}
        <Grid item>
          <Button
            sx={{ height: '36px' }}
            disableElevation
            disabled={postInProgress || postCompleted || postError || blogId === '0'}
            size="small"
            variant="contained"
            color="primary"
            onClick={_onPost}
          >
            {postInProgress ? (
              <CircularProgress size={20} color="primary" />
            ) : postCompleted ? (
              <CheckCircleIcon color="success" />
            ) : postError ? (
              <ErrorIcon color="error" />
            ) : disabled ? (
              `Comments disabled for this post`
            ) : (
              'Post'
            )}
          </Button>
        </Grid>
      </Grid>
    </Grid>
  );
};
