import { Tooltip, TooltipProps /*styled, tooltipClasses,*/, useTheme } from '@mui/material';
import React from 'react';

interface GenericTooltipProps extends TooltipProps {
  disabled?: boolean;
  padding?: number;
}

export const GenericTooltip = ({
  disabled,
  open,
  title,
  arrow = true,
  enterDelay = 400,
  padding = 12,
  ...props
}: GenericTooltipProps) => {
  const theme = useTheme();
  return (
    <>
      {!disabled ? (
        <Tooltip
          {...props}
          open={open}
          enterDelay={enterDelay}
          title={title}
          arrow
          // sx={{
          //   [`& .${tooltipClasses.tooltip}`]: {
          //     backgroundColor: '#fff',
          //   },
          // }}
          slotProps={{
            tooltip: {
              sx: {
                backgroundColor:
                  theme.palette.mode === 'dark' ? theme.palette.custom.tooltip : theme.palette.primary.light,
                boxShadow: theme.shadows[theme.palette.mode === 'dark' ? 0 : 3],
                opacity: 0.9,
                padding: `${padding}px`,
                border: `0px solid #669692`,
                marginTop: '6px !important',
              },
            },
            arrow: {
              sx: {
                color: theme.palette.mode === 'dark' ? theme.palette.custom.tooltip : theme.palette.primary.light,
                '&::before': {
                  // boxShadow: '5px 5px 3px #B6B6B6',
                  border: `1px solid ${theme.palette.mode === 'dark' ? 'transparent' : 'lightgray'}`,
                },
              },
            },
          }}
        >
          <div>{props.children}</div>
        </Tooltip>
      ) : (
        props.children
      )}
    </>
  );
};
