import { Divider, Grid, Paper, Typography } from '@mui/material';
import { useCommentsFirestore } from 'stores/blog/comments.firestore';
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { selectComments } from 'stores/blog/blog.selectors';
import { IComment } from 'stores/blog/models';
import { blogActions } from 'stores/blog/blog.redux';
import { doc, setDoc } from 'firebase/firestore';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { makeDocHash } from 'database/firebase/firebase-helper';
import { CommentForm } from './comment-form';
import { LoadingSkeleton } from './comment-skeleton';
import { Reply } from './comment-reply';

interface CommentProps {
  blogId: string;
}

export const Comment = ({ blogId, ...props }: CommentProps) => {
  const dispatch = useDispatch();
  const { loading: loadingComments } = useCommentsFirestore(blogId);
  const comments = useSelector(selectComments);
  const { firestore } = React.useContext(FirebaseContext);
  React.useEffect(() => {
    return () => {
      dispatch(blogActions.resetComments());
    };
  }, [dispatch]);

  // TODO: @JAKE - Implement react-hook-form for comment submission and saga for dispatching event
  const onPost = ({ comment: _comment }) => {
    return setDoc(doc(firestore, `blogs/${blogId}/comments`, makeDocHash(20)), _comment);
  };

  return (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Divider />
      </Grid>
      <Grid item container xs={12} spacing={3}>
        {/* TODO: @JAKE - Remove hard-coded disable after adding collection creation */}
        <CommentForm blogId={blogId} onPost={onPost} disabled={blogId === '0'} />
      </Grid>
      <Grid item xs={12}>
        {loadingComments ? <LoadingSkeleton /> : <Replies blogId={blogId} comments={comments} />}
      </Grid>
    </Grid>
  );
};

const Replies = ({ blogId, comments }: { blogId: string; comments: IComment[] }) => {
  return (
    <Grid container spacing={0}>
      <Grid item xs={12}>
        <Typography variant="h6" component="h6" color="text.primary">
          {'Comments'}
        </Typography>
      </Grid>
      <Grid item xs={12}>
        {comments?.length > 0 ? (
          <Paper
            elevation={0}
            sx={{ padding: '12px 0px !important', backgroundColor: 'transparent', backdropFilter: 'blur(5px)' }}
          >
            <Grid container spacing={0}>
              {comments?.map((comment, index) => (
                <Grid key={index} item container spacing={3}>
                  <Grid item xs={12}>
                    <Reply
                      blogId={blogId}
                      comment={comment}
                      level={0}
                      lastComment={index === comments.length - 1 && comment.replies.length === 0}
                      commentParentsRemaining={index !== comments.length - 1}
                    />
                  </Grid>
                </Grid>
              ))}
            </Grid>
          </Paper>
        ) : (
          <Typography variant="body1" color="text.primary">
            {'No comments yet.'}
          </Typography>
        )}
      </Grid>
    </Grid>
  );
};
