import { createSelector } from '@reduxjs/toolkit';
import { RootState } from 'types';
import { initialState } from './blog.redux';

const selectDomain = (state: RootState) => state?.blogs || initialState;

export const selectBlogs = createSelector([selectDomain], state => state);

export const selectBlog = createSelector([selectDomain, (_, id: string) => id], (state, id) =>
  state.blogs.find(item => item.id === id),
);

export const selectComments = createSelector([selectDomain], state => state.comments);
