import { useNavigate } from 'react-router-dom';

export const useNavigation = () => {
  const navigate = useNavigate();
  return {
    home: () => navigate('/'),
    cv: () => {
      window.open('/assets/cv.pdf', '_blank');
    },
    penn: () => (window.location.href = 'https://www.ling.upenn.edu/people/alexander-hamo'),
    blogs: () => navigate('/blog'),
    blog: (id: string) => navigate(`/blog/${id}`),
  };
};
