import {
  Button,
  Divider,
  Grid,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
} from '@mui/material';
import { useMenu } from './menu';
import { GenericDrawer } from 'app/components/drawer/generic-drawer';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { ProfileAvatar } from 'app/pages/profile/profile-avatar';
import React from 'react';
import { EAuthType, useAuth } from 'app/utils/user-helper';
import { SignUpActions } from 'app/pages/signin/signup-actions';
import ArticleIcon from '@mui/icons-material/Article';
import SchoolIcon from '@mui/icons-material/School';
import FileOpenIcon from '@mui/icons-material/FileOpen';

interface MenuDrawerProps {
  open: boolean;
  setOpen: (open: boolean) => void;
}

const getMenuItemIcon = (title: string) => {
  switch (title.toLowerCase()) {
    case 'cv':
      return <FileOpenIcon />;
    case 'blog':
      return <ArticleIcon />;
    case 'penn':
      return <SchoolIcon />;
    default:
      return '';
  }
};

export const MenuDrawer = ({ open, setOpen, ...props }: MenuDrawerProps) => {
  const { user } = React.useContext(FirebaseContext);
  const { signOutUser } = useAuth();

  const { menuItems } = useMenu();

  return (
    <>
      <GenericDrawer
        open={open}
        onClose={() => setOpen(false)}
        sx={{
          '& .MuiPaper-root': {
            boxShadow: '6px 4px 10px rgb(0, 0, 0, 0.2) !important',
          },
        }}
      >
        <div style={{ width: '230px', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
          <Grid container>
            <Grid item xs={12}>
              {user ? (
                <>
                  <List>
                    <ListItemButton>
                      <ListItemIcon>
                        <ProfileAvatar mobile size="24px" />
                      </ListItemIcon>
                      <ListItemText>{user.displayName}</ListItemText>
                    </ListItemButton>
                    {/* <ListItemButton>
                      <ListItemIcon>
                        <SettingsIcon />
                      </ListItemIcon>
                      <ListItemText>{'Account settings'}</ListItemText>
                    </ListItemButton> */}
                    <ListItem>
                      <Button
                        variant="contained"
                        sx={{ borderRadius: '28px', height: '28px' }}
                        size="small"
                        color="primary"
                        disableElevation
                        onClick={() => {
                          signOutUser({ authType: EAuthType.google });
                        }}
                      >
                        Sign Out
                      </Button>
                    </ListItem>
                  </List>
                </>
              ) : (
                <ListItem sx={{ padding: '24px 16px' }}>
                  <SignUpActions onSignInClick={() => setOpen(false)} onSignUpClick={() => setOpen(false)} />
                </ListItem>
              )}
            </Grid>
          </Grid>
          <Divider />
          <List sx={{ overflow: 'auto', paddingBottom: '24px' }}>
            {menuItems.map((item, index) => (
              <>
                <ListItemButton
                  key={index}
                  onClick={() => {
                    item.onClick();
                    setOpen(false);
                  }}
                >
                  <ListItemIcon>{getMenuItemIcon(item.title)}</ListItemIcon>
                  <ListItemText>{item.title}</ListItemText>
                </ListItemButton>
                {/* <Divider sx={{ margin: '0px 16px' }} /> */}
              </>
            ))}
          </List>
        </div>
      </GenericDrawer>
    </>
  );
};
