import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { useDispatch } from 'react-redux';
import { profileActions } from 'stores/profile/profile.redux';
import React from 'react';
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signInWithPopup,
  signInWithRedirect,
  signOut,
  updateProfile,
} from 'firebase/auth';
import { IProfileSigninType } from 'stores/profile/profile.models';
import _ from 'lodash';
import { useMediaQuery, useTheme } from '@mui/material';

export const getUserInitials = (displayName: string): string => {
  const nameParts = displayName?.split(' ');
  if (nameParts?.length === 1) {
    return nameParts[0].charAt(0).toUpperCase();
  } else if (nameParts?.length > 1) {
    return nameParts[0].charAt(0).toUpperCase() + nameParts[1].charAt(0).toUpperCase();
  } else {
    return 'N/A';
  }
};

export const getUserFirstName = (displayName: string): string => {
  const nameParts = displayName.split(' ');
  if (nameParts.length > 0) {
    return nameParts[0];
  } else {
    return displayName;
  }
};

export const getUserLastName = (displayName: string): string => {
  const nameParts = displayName.split(' ');
  if (nameParts.length > 1) {
    return nameParts[1];
  } else {
    return '';
  }
};

export enum EAuthType {
  google,
  email,
  github,
}

export const useAuth = () => {
  const dispatch = useDispatch();
  const { auth, googleAuthProvider, githubAuthProvider, setUser } = React.useContext(FirebaseContext);
  const theme = useTheme();
  const desktop = useMediaQuery(theme.breakpoints.up('sm'));

  const signOutUser = ({ authType }: { authType: EAuthType }) => {
    signOut(auth)
      .then(e => {
        dispatch(profileActions.toggleProfileDrawer({ open: false }));
        return Promise.resolve(e);
      })
      .catch(error => {
        console.info('@JAKE - Sign out error', error);
        return Promise.reject(error);
      });
  };

  const signInUser = ({
    authType,
    emailPassword,
  }: {
    authType: EAuthType;
    emailPassword?: { email: string; password: string };
  }) => {
    switch (authType) {
      case EAuthType.google:
        switch (desktop) {
          case false:
            return signInWithRedirect(auth, googleAuthProvider)
              .then(result => {
                dispatch(profileActions.setLoginDialogOpen(undefined));
                return Promise.resolve(result);
              })
              .catch(error => {
                console.info('@JAKE - LOGIN GOOGLE ERROR', error);
                return Promise.reject(error);
              });
          case true:
            return signInWithPopup(auth, googleAuthProvider)
              .then(result => {
                dispatch(profileActions.setLoginDialogOpen(undefined));
                return Promise.resolve(result);
              })
              .catch(error => {
                console.info('@JAKE - LOGIN GOOGLE ERROR', error);
                return Promise.reject(error);
              });
          default:
            return Promise.reject();
        }
      case EAuthType.email:
        if (emailPassword) {
          return signInWithEmailAndPassword(auth, emailPassword.email, emailPassword.password)
            .then(result => {
              dispatch(profileActions.setLoginDialogOpen(IProfileSigninType.signIn));
              return Promise.resolve(result);
            })
            .catch(error => {
              console.info('@JAKE - LOGIN EMAIL/PASSWORD ERROR', error);
              return Promise.reject(error);
            });
        } else {
          return Promise.reject('Email and password are required');
        }
      case EAuthType.github:
        switch (desktop) {
          case false:
            return signInWithPopup(auth, githubAuthProvider)
              .then(result => {
                dispatch(profileActions.setLoginDialogOpen(undefined));
                return Promise.resolve(result);
              })
              .catch(error => {
                //auth/account-exists-with-different-credential
                console.info('@JAKE - LOGIN GITHUB ERROR REDIRECT', error);
                return Promise.reject(error);
              });
          case true:
            return signInWithPopup(auth, githubAuthProvider)
              .then(result => {
                dispatch(profileActions.setLoginDialogOpen(undefined));
                return Promise.resolve(result);
              })
              .catch(error => {
                //auth/account-exists-with-different-credential
                console.info('@JAKE - LOGIN GITHUB ERROR POPUP', error);
                return Promise.reject(error);
              });
          default:
            return Promise.reject();
        }
      default:
        return Promise.reject();
    }
  };

  const createUser = ({
    authType,
    username,
    email,
    password,
  }: {
    authType: EAuthType;
    username: string;
    email: string;
    password: string;
  }) => {
    return createUserWithEmailAndPassword(auth, email, password)
      .then(result => {
        updateProfile(result.user, {
          displayName: username,
        }).then(() => {
          setUser(_.cloneDeep(auth.currentUser));
          return Promise.resolve(result);
        });
      })
      .catch(error => {
        console.info('@JAKE - LOGIN ERROR', error);
        return Promise.reject(error);
      });
  };

  return { signOutUser, signInUser, createUser };
};
