import React, { createContext } from 'react';
import './App.css';
import { PaletteMode, StyledEngineProvider, ThemeProvider, createTheme } from '@mui/material';
import { getDesignTokens } from '../../styles/theme';
import { router } from '../routes/routes';
import { RouterProvider } from 'react-router-dom';
import { firebaseConfig } from '../../database/firebase/firebase-config';
import { initializeApp, FirebaseApp } from 'firebase/app';
import { getFirestore, Firestore } from 'firebase/firestore';
import {
  Auth,
  GithubAuthProvider,
  GoogleAuthProvider,
  User,
  getAuth,
  getRedirectResult,
  onAuthStateChanged,
} from 'firebase/auth';
import { Provider } from 'react-redux';
import { configureAppStore } from 'redux-config/configure-store';
import { Global } from 'app/components/global';

export const store = configureAppStore();
const app = initializeApp(firebaseConfig);
const firestore = getFirestore(app);
const auth = getAuth(app);
const googleAuthProvider = new GoogleAuthProvider();
const githubAuthProvider = new GithubAuthProvider();

export const FirebaseContext = createContext<{
  firebaseApp: FirebaseApp;
  firestore: Firestore;
  auth: Auth;
  googleAuthProvider: GoogleAuthProvider;
  githubAuthProvider?: GithubAuthProvider;
  user?: User;
  setUser?: any;
}>({
  firebaseApp: app,
  firestore: firestore,
  auth,
  googleAuthProvider,
  githubAuthProvider,
});

export const App: React.FC = () => {
  const [mode, setMode] = React.useState<PaletteMode>('light');
  const [user, setUser] = React.useState<User | undefined>();

  const activateDarkMode = React.useCallback((e: any) => {
    if (e.matches) {
      setMode('dark');
      document.body.style.backgroundColor = '#334247';
    } else {
      setMode('light');
      document.body.style.backgroundColor = '#fff';
    }
  }, []);

  React.useEffect(() => {
    googleAuthProvider.setCustomParameters({
      prompt: 'select_account',
    });
  }, []);

  React.useEffect(() => {
    onAuthStateChanged(auth, newUser => {
      if (newUser) {
        console.info('@JAKE - USER', newUser);
        setUser(newUser);
      } else {
        setUser(undefined);
      }
    });
  }, []);

  React.useEffect(() => {
    getRedirectResult(auth)
      .then(result => {
        console.info('@JAKE - RESULT', result);
        setUser(result?.user);
      })
      .catch(error => {
        console.info('@JAKE - REDIRECT RESULT ERROR', error);
      });
  }, []);

  React.useEffect(() => {
    const themePreference = window.matchMedia('(prefers-color-scheme: dark)');
    activateDarkMode(themePreference);
    themePreference.addEventListener('change', e => activateDarkMode(e));
  }, [activateDarkMode]);

  const theme = React.useMemo(() => createTheme(getDesignTokens(mode)), [mode]);

  const _setUser = user => {
    console.info('@JAKE - SETTING NEW USER', user);
    setUser(user);
  };

  return (
    <StyledEngineProvider injectFirst>
      {/* <CssBaseline /> */}
      <ThemeProvider theme={theme}>
        <div
          className="App"
          style={{
            height: '100vh',
            overflow: 'auto',
            backgroundColor: 'transparent',
          }}
        >
          <Provider store={store}>
            <FirebaseContext.Provider
              value={{
                firebaseApp: app,
                firestore: firestore,
                auth,
                googleAuthProvider,
                githubAuthProvider,
                user,
                setUser: _setUser,
              }}
            >
              <Global>
                <RouterProvider router={router} />
              </Global>
            </FirebaseContext.Provider>
          </Provider>
        </div>
      </ThemeProvider>
    </StyledEngineProvider>
  );
};
