import moment from 'moment';

export const calculateTimeSince = date => {
  const now = moment();
  const diff = moment.duration(now.diff(date));

  if (diff.asSeconds() < 60) {
    return `${Math.floor(diff.asSeconds())} ${Math.floor(diff.asSeconds()) === 1 ? 'second' : 'seconds'} ago`;
  } else if (diff.asMinutes() < 60) {
    return `${Math.floor(diff.asMinutes())} ${Math.floor(diff.asMinutes()) === 1 ? 'minute' : 'minutes'} ago`;
  } else if (diff.asHours() < 24) {
    return `${Math.floor(diff.asHours())} ${Math.floor(diff.asHours()) === 1 ? 'hour' : 'hours'} ago`;
  } else if (diff.asDays() < 30) {
    return `${Math.floor(diff.asDays())} ${Math.floor(diff.asDays()) === 1 ? 'day' : 'days'} ago`;
  } else if (diff.asMonths() < 12) {
    return `${Math.floor(diff.asMonths())} ${Math.floor(diff.asMonths()) === 1 ? 'month' : 'months'} ago`;
  } else {
    return `${Math.floor(diff.asYears())} ${Math.floor(diff.asYears()) === 1 ? 'year' : 'years'} ago`;
  }
};
