import { ClickAwayListener, Drawer, DrawerProps } from '@mui/material';

interface GenericDrawerProps extends DrawerProps {
  onClose?: () => void;
  width?: number;
}

export const GenericDrawer = ({
  open,
  onClose,
  anchor = 'left',
  variant = 'persistent',
  width,
  children,
  ...props
}: GenericDrawerProps) => {
  return (
    <ClickAwayListener
      onClickAway={e => {
        if (open) {
          onClose?.();
          e.preventDefault();
        }
      }}
    >
      <Drawer
        hideBackdrop
        anchor={anchor}
        variant={variant}
        open={open}
        onClose={onClose}
        elevation={0}
        {...props}
        PaperProps={{
          sx: {
            ...props.PaperProps?.sx,
            top: '70px',
            width: width ? `${width}px` : undefined,
          },
        }}
      >
        {children}
      </Drawer>
    </ClickAwayListener>
  );
};
