import { Breadcrumbs, Divider, Grid, Link, Typography } from '@mui/material';
import { useNavigation } from 'app/utils/hooks/use-navigation';
import moment from 'moment';
import { useSelector } from 'react-redux';
import { useParams } from 'react-router-dom';
import { useBlogFirestore } from 'stores/blog/blog.firestore';
import { selectBlog } from 'stores/blog/blog.selectors';
import { useCommentsFirestore } from 'stores/blog/comments.firestore';
import { IBlog } from 'stores/blog/models';
import { Comment } from './comment';

interface BlogProps {}

export const Blog = ({ ...props }: BlogProps) => {
  const { id } = useParams();
  useBlogFirestore();
  useCommentsFirestore(id);
  const blog = useSelector(state => selectBlog(state, id));

  return (
    <Grid container>
      <Grid item xs={12}>
        <BlogPost blog={blog} />
      </Grid>
    </Grid>
  );
};

const BlogPost = ({ blog }: { blog: IBlog }) => {
  const { blogs } = useNavigation();
  return (
    <>
      {blog && (
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Breadcrumbs>
              <Link underline="hover" color="inherit" onClick={() => blogs()}>
                Blog
              </Link>
              <Typography color="text.primary">{blog.title}</Typography>
            </Breadcrumbs>
            <Divider sx={{ marginTop: '12px' }} />
          </Grid>
          <Grid item xs={12}>
            <Grid container>
              <Grid item xs={12}>
                <Typography variant="h5" component="h5" color="text.primary">
                  {blog.title}
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Typography variant="subtitle1" color="text.secondary">
                  {moment(blog.date).format('MMMM DD, YYYY')}
                </Typography>
              </Grid>
            </Grid>
          </Grid>
          <Grid item xs={12}>
            <Grid container spacing={3}>
              <Grid item xs={12}>
                <Typography variant="h6" component="h6" color="text.primary">
                  {blog.header}
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Typography variant="body1" color="text.primary">
                  {blog.content}
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Comment blogId={blog.id} />
              </Grid>
            </Grid>
          </Grid>
        </Grid>
      )}
    </>
  );
};
