import { SigninDialog } from 'app/pages/signin/signin-dialog';
import { isNullOrUndefined } from 'app/utils/helper';
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useInjectReducer } from 'redux-injectors';
import { profileActions, profileReducer, profileSliceKey } from 'stores/profile/profile.redux';
import { selectSigninDialogOpen } from 'stores/profile/profile.selectors';

import 'locales/i18n';

interface GlobalProps {
  children: JSX.Element;
}

export const Global = ({ children, ...props }: GlobalProps) => {
  useInjectReducer({ key: profileSliceKey, reducer: profileReducer });
  const loginDialogOpen = useSelector(selectSigninDialogOpen);
  const dispatch = useDispatch();
  return (
    <>
      {children}
      {<SigninDialog open={!isNullOrUndefined(loginDialogOpen)} onClose={() => dispatch(profileActions.setLoginDialogOpen(undefined))} />}
    </>
  );
};
