import { AppBar, Toolbar, Typography, Button, Grid, useTheme } from '@mui/material';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import React from 'react';
import { MediaQuery } from './media-query';
import { MenuDrawer } from './menu-drawer';
import { useMenu } from './menu';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { useDispatch, useSelector } from 'react-redux';
import { profileActions } from 'stores/profile/profile.redux';
import { selectProfile } from 'stores/profile/profile.selectors';
import { GenericTooltip } from 'app/components/tooltip/generic-tooltip';
import { ProfileTooltip } from 'app/pages/profile/profile-tooltip';
import { ProfileAvatar } from 'app/pages/profile/profile-avatar';
import { useNavigation } from 'app/utils/hooks/use-navigation';
import { SignUpActions } from 'app/pages/signin/signup-actions';

interface HeaderProps {}

export const Header = ({ ...props }: HeaderProps) => {
  const dispatch = useDispatch();
  const [drawerOpen, setDrawerOpen] = React.useState<boolean>(false);
  const { drawerOpen: profileDrawerOpen } = useSelector(selectProfile);
  const { user } = React.useContext(FirebaseContext);
  const { menuItems } = useMenu();
  const theme = useTheme();
  const { home } = useNavigation();

  return (
    <>
      <AppBar
        position="sticky"
        sx={{
          height: '70px',
          justifyContent: 'center',
          backgroundColor: theme.palette.mode === 'light' ? '#fff' : undefined,
          borderBottom: '1px solid rgba(149,153,157,0.34)',
        }}
        elevation={0}
        color="default"
      >
        <Toolbar
          sx={{
            paddingLeft: 'calc(40% - 17em) !important',
            paddingRight: 'calc(40% - 17em) !important',
            marginLeft: '24px',
            marginRight: '24px',
          }}
        >
          <MediaQuery maxWidth="xs">
            <IconButton
              size="large"
              edge="start"
              color="inherit"
              aria-label="menu"
              sx={{ mr: 2 }}
              onClick={e => {
                setDrawerOpen(e => !e);
                e.preventDefault();
                e.stopPropagation();
              }}
            >
              <MenuIcon />
            </IconButton>
          </MediaQuery>
          <Typography
            variant="h5"
            component="div"
            sx={{ flexGrow: 0, display: 'flex', minWidth: '180px', cursor: 'pointer' }}
            onClick={() => home()}
          >
            alexander hamo
          </Typography>
          <MediaQuery minWidth="sm">
            <Grid container justifyContent="flex-end" alignItems="center" sx={{ display: 'flex', flexGrow: 1 }}>
              {/* Menu Items */}
              {menuItems.map((item, index) => (
                <Grid key={index} item>
                  <Button size="small" className="nav-button" color="inherit" onClick={item.onClick}>
                    {item.title}
                  </Button>
                </Grid>
              ))}
              {/* User Avator / Sign In */}
              <Grid item sx={{ marginLeft: '18px' }}>
                {user ? (
                  <GenericTooltip
                    open={profileDrawerOpen}
                    enterDelay={500}
                    leaveDelay={200}
                    placement="bottom-end"
                    title={
                      <ProfileTooltip
                        onClickAway={() => {
                          dispatch(profileActions.toggleProfileDrawer({ open: false }));
                        }}
                      />
                    }
                    disableHoverListener
                    arrow
                  >
                    <ProfileAvatar mobile={false} />
                  </GenericTooltip>
                ) : (
                  <SignUpActions />
                )}
              </Grid>
            </Grid>
          </MediaQuery>
        </Toolbar>
        {/* <Divider sx={{ backgroundColor: 'rgba(149,153,157,0.14)' }} /> */}
      </AppBar>
      <MediaQuery maxWidth="xs">
        <MenuDrawer open={drawerOpen} setOpen={setDrawerOpen} />
      </MediaQuery>
    </>
  );
};
