import { ClickAwayListener, Grid, Typography, Button } from '@mui/material';
import { FirebaseContext } from 'app/applicationroot/applicationroot';
import { EAuthType, useAuth } from 'app/utils/user-helper';
import React from 'react';

export const ProfileTooltip = ({ onClickAway }) => {

  const { signOutUser } = useAuth();
  const { user } = React.useContext(FirebaseContext);
  return (
    <ClickAwayListener onClickAway={onClickAway}>
      <Grid container spacing={0}>
        <Grid item xs={12}>
          <Typography variant="h6" color="text.primary">
            {user.displayName}
          </Typography>
        </Grid>
        <Grid item xs={12}>
          <Typography variant="body1" color="text.primary">
            {user.email}
          </Typography>
        </Grid>
        <Grid item xs={12} justifyContent="flex-end" sx={{ display: 'flex', marginTop: '24px' }}>
          <Button
            variant="contained"
            size="small"
            disableElevation
            onClick={() => {
              signOutUser({ authType: EAuthType.google });
            }}
          >
            Sign Out
          </Button>
        </Grid>
      </Grid>
    </ClickAwayListener>
  );
};
