import { Divider, Grid, Link, Typography } from '@mui/material';
import { useSelector } from 'react-redux';
import { selectBlogs } from 'stores/blog/blog.selectors';
import { useBlogFirestore } from 'stores/blog/blog.firestore';
import { useNavigation } from 'app/utils/hooks/use-navigation';
import { IBlog } from 'stores/blog/models';
import moment from 'moment';

interface BlogsProps {}

export const Blogs = ({ ...props }: BlogsProps) => {
  useBlogFirestore();
  const { blogs } = useSelector(selectBlogs);

  return (
    <Grid container>
      {blogs.map((blog, index) => (
        <Grid item key={index} xs={12}>
          <BlogPreview blog={blog} />
          {index !== blogs.length - 1 && (
            <Grid item xs={12} sx={{ margin: '24px 0px' }}>
              <Divider />
            </Grid>
          )}
        </Grid>
      ))}
    </Grid>
  );
};

const BlogPreview = ({ blog }: { blog: IBlog }) => {
  const { blog: blogNavigate } = useNavigation();
  return (
    <>
      {blog && (
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Grid container>
              <Grid item xs={12}>
                <Typography variant="h5" color="text.primary">
                  <Link
                    color="text.primary"
                    onClick={() => {
                      blogNavigate(blog.id);
                    }}
                  >
                    {blog.title}
                  </Link>
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Typography variant="subtitle1" color="text.secondary">
                  {moment(blog.date).format('MMMM DD, YYYY')}
                </Typography>
              </Grid>
            </Grid>
          </Grid>
          <Grid item xs={12}>
            <Grid container spacing={3}>
              <Grid item xs={12}>
                <Typography variant="h6" component="h6" color="text.primary">
                  {blog.header}
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <Typography variant="body1" color="text.primary">
                  {blog.content.length > 100 ? `${blog.content.substring(0, 100)}...` : blog.content}
                </Typography>
              </Grid>
            </Grid>
          </Grid>
        </Grid>
      )}
    </>
  );
};
